{
  "mechanisms": [
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Stage-1 action values are updated by the stage-2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lambd",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[a1] = q_stage1_mf[a1] + learning_rate * lambd * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "value_decay",
      "title": "Value Decay",
      "description": "Q-values for unchosen actions and unvisited states decay towards zero on each trial.",
      "params": [
        {
          "name": "decay_rate",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[1 - a1] *= (1.0 - decay_rate)\n\n        q_stage2_mf[state_idx, 1 - a2] *= (1.0 - decay_rate)\n\n        q_stage2_mf[1 - state_idx, :] *= (1.0 - decay_rate)",
      "expressible_in_slots": true
    }
  ]
}
